import React from "react";

import {
    VoiceBroadcastControl,
    VoiceBroadcastHeader,
    VoiceBroadcastPlayback,
    VoiceBroadcastPlaybackState,
} from "../..";
import Spinner from "../../../components/views/elements/Spinner";
import { useVoiceBroadcastPlayback } from "../../hooks/useVoiceBroadcastPlayback";
import { Icon as PlayIcon } from "../../../../res/img/element-icons/play.svg";
import { Icon as PauseIcon } from "../../../../res/img/element-icons/pause.svg";
import { _t } from "../../../languageHandler";
import Clock from "../../../components/views/audio_messages/Clock";
import SeekBar from "../../../components/views/audio_messages/SeekBar";

interface VoiceBroadcastPlaybackBodyProps {
    playback: VoiceBroadcastPlayback;
}

export const VoiceBroadcastPlaybackBody: React.FC<VoiceBroadcastPlaybackBodyProps> = ({
    playback,
}) => {
    const {
        duration,
        liveness,
        room,
        sender,
        toggle,
        playbackState,
    } = useVoiceBroadcastPlayback(playback);

    let control: React.ReactNode;

    if (playbackState === VoiceBroadcastPlaybackState.Buffering) {
        control = <Spinner />;
    } else {
        let controlIcon: React.FC<React.SVGProps<SVGSVGElement>>;
        let controlLabel: string;

        switch (playbackState) {
            case VoiceBroadcastPlaybackState.Stopped:
                controlIcon = PlayIcon;
                controlLabel = _t("play voice broadcast");
                break;
            case VoiceBroadcastPlaybackState.Paused:
                controlIcon = PlayIcon;
                controlLabel = _t("resume voice broadcast");
                break;
            case VoiceBroadcastPlaybackState.Playing:
                controlIcon = PauseIcon;
                controlLabel = _t("pause voice broadcast");
                break;
        }

        control = <VoiceBroadcastControl
            label={controlLabel}
            icon={controlIcon}
            onClick={toggle}
        />;
    }

    return (
        <div className="mx_VoiceBroadcastBody">
            <VoiceBroadcastHeader
                live={liveness}
                microphoneLabel={sender?.name}
                room={room}
                showBroadcast={true}
            />
            <div className="mx_VoiceBroadcastBody_controls">
                { control }
            </div>
            <div className="mx_VoiceBroadcastBody_timerow">
                <SeekBar playback={playback} />
                <Clock seconds={duration} />
            </div>
        </div>
    );
};

    const devicesMenu = state.showDeviceSelect && pipRef.current
        ? <IconizedContextMenu
            mountAsChild={false}
            onFinished={() => {}}
            {...toLeftOrRightOf(pipRef.current.getBoundingClientRect(), 0)}
        >
            <IconizedContextMenuOptionList>
                { deviceOptions }
            </IconizedContextMenuOptionList>
        </IconizedContextMenu>
        : null;

    return <div
        className="mx_VoiceBroadcastBody mx_VoiceBroadcastBody--pip"
        ref={pipRef}
    >
        <VoiceBroadcastHeader
            onCloseClick={voiceBroadcastPreRecording.cancel}
            onMicrophoneLineClick={onMicrophoneLineClick}
            room={voiceBroadcastPreRecording.room}
            microphoneLabel={state.device?.label || _t('Default Device')}
            showClose={true}
        />
        <AccessibleButton
            className="mx_VoiceBroadcastBody_blockButton"
            kind="danger"
            onClick={voiceBroadcastPreRecording.start}
        >
            <LiveIcon className="mx_Icon mx_Icon_16" />
            { _t("Go live") }
        </AccessibleButton>
        { devicesMenu }
    </div>;
};

