    }

    public async start(): Promise<void> {
        this.setState(VoiceBroadcastPlaybackState.Buffering);
        await this.enqueueChunks();
        const chunkEvents = this.chunkEvents.getEvents();

        const toPlay = this.getInfoState() === VoiceBroadcastInfoState.Stopped
            ? chunkEvents[0] // start at the beginning for an ended voice broadcast
            : chunkEvents[chunkEvents.length - 1]; // start at the current chunk for an ongoing voice broadcast

        if (this.playbacks.has(toPlay?.getId() || "")) {
            return this.playEvent(toPlay);
        }

        this.setState(VoiceBroadcastPlaybackState.Buffering);
    }

    public stop(): void {
        this.setState(VoiceBroadcastPlaybackState.Stopped);
        this.currentlyPlaying = null;
        this.setPosition(0);
    }

    public pause(): void {
        // stopped voice broadcasts cannot be paused
        if (this.getState() === VoiceBroadcastPlaybackState.Stopped) return;

        this.setState(VoiceBroadcastPlaybackState.Paused);
        if (!this.currentlyPlaying) return;
        this.getPlaybackForEvent(this.currentlyPlaying)?.pause();
    }

    public resume(): void {
        if (!this.currentlyPlaying) {
            // no playback to resume, start from the beginning
            this.start();
            return;
        }

        this.setState(VoiceBroadcastPlaybackState.Playing);
        this.getPlaybackForEvent(this.currentlyPlaying)?.play();
    }

    /**
     * Toggles the playback:
     * stopped → playing
     * playing → paused
     * paused → playing
     */
    public async toggle() {
        if (this.state === VoiceBroadcastPlaybackState.Stopped) {
            await this.start();
            return;
        }

        if (this.state === VoiceBroadcastPlaybackState.Paused) {
            this.resume();
            return;
        }

        this.pause();
    }

    public getState(): VoiceBroadcastPlaybackState {
        return this.state;
    }

    private setState(state: VoiceBroadcastPlaybackState): void {
        if (this.state === state) {
            return;
        }

        this.state = state;
        this.updateLiveness();
        this.emit(VoiceBroadcastPlaybackEvent.StateChanged, state, this);
    }

    public getInfoState(): VoiceBroadcastInfoState {
        return this.infoState;
    }

    private setInfoState(state: VoiceBroadcastInfoState): void {
        if (this.infoState === state) {
            return;
        }

        this.infoState = state;
        this.updateLiveness();
        this.emit(VoiceBroadcastPlaybackEvent.InfoStateChanged, state);
    }

    public getLiveness(): VoiceBroadcastLiveness {
        return this.liveness;
    }

    private updateLiveness(): void {
        let liveness: VoiceBroadcastLiveness;

        if (
            this.infoState === VoiceBroadcastInfoState.Stopped
            || this.state === VoiceBroadcastPlaybackState.Stopped
        ) {
            liveness = "not-live";
        } else if (
            this.infoState === VoiceBroadcastInfoState.Paused
            || this.state === VoiceBroadcastPlaybackState.Paused
            || this.state === VoiceBroadcastPlaybackState.Buffering
        ) {
            liveness = "grey";
        } else {
            liveness = "live";
        }

        if (this.liveness === liveness) return;

        this.liveness = liveness;
        this.emit(VoiceBroadcastPlaybackEvent.LivenessChanged, liveness);
    }

    public destroy(): void {
        this.chunkRelationHelper.destroy();
        this.infoRelationHelper.destroy();
        this.removeAllListeners();

        this.chunkEvents = new VoiceBroadcastChunkEvents();
        this.playbacks.forEach(p => p.destroy());
        this.playbacks = new Map<string, Playback>();
    }
}

